SELECT *, LAST_VALUE(discount) IGNORE NULLS OVER (PARTITION BY customer_id ORDER BY shipping_fee, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_discount, AVG(shipping_fee) OVER (PARTITION BY status ORDER BY discount, id ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) AS shipping_fee_avg_2, AVG(discount) OVER (ORDER BY amount, id ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) AS discount_avg_2, AVG(shipping_fee) OVER (PARTITION BY channel, status ORDER BY discount, id ROWS BETWEEN 2 PRECEDING AND 1 PRECEDING) AS shipping_fee_avg_2_prior FROM orders;
